Hub.PickBestCoin = function(self, pos, coins, mpos)
	if not (self.Config.Toggles.AutoFarmAvoidMurder and mpos) then
		local best, bd = nil, math.huge;
		for _, v in ipairs(coins) do
			local d = (v.Position - pos).Magnitude;
			if (d < bd) then
				bd = d;
				best = v;
			end
		end
		return best;
	end
	local AVOID_DIST = 40;
	local safe, sd = nil, math.huge;
	local far, fd = nil, -1;
	for _, v in ipairs(coins) do
		local md = Vector3.new(v.Position.X - mpos.X, 0, v.Position.Z - mpos.Z).Magnitude;
		if (md > fd) then
			fd = md;
			far = v;
		end
		if (md >= AVOID_DIST) then
			local d = (v.Position - pos).Magnitude;
			if (d < sd) then
				sd = d;
				safe = v;
			end
		end
	end
	if safe then
		return safe;
	end
	if (far and (fd >= (AVOID_DIST * 0.6))) then
		return far;
	end
	return nil;
end;
Hub.AvoidSteer = function(self, cur, dest, mpos)
	if not (self.Config.Toggles.AutoFarmAvoidMurder and mpos) then
		return dest;
	end
	local AVOID_DIST = 40;
	local dm = Vector3.new(cur.X - mpos.X, 0, cur.Z - mpos.Z).Magnitude;
	if (dm >= AVOID_DIST) then
		return dest;
	end
	local away = Vector3.new(cur.X - mpos.X, 0, cur.Z - mpos.Z);
	if (away.Magnitude < 0.1) then
		away = Vector3.new(1, 0, 0);
	end
	away = away.Unit;
	local want = Vector3.new(dest.X - cur.X, 0, dest.Z - cur.Z);
	local mag = want.Magnitude;
	if (mag < 0.1) then
		return dest;
	end
	local weight = 1 + ((1 - (dm / AVOID_DIST)) * 2);
	local blend = want.Unit + (away * weight);
	if (blend.Magnitude < 0.1) then
		blend = away;
	else
		blend = blend.Unit;
	end
	local np = cur + (blend * mag);
	return Vector3.new(np.X, dest.Y, np.Z);
end;
Hub.FarmStepMove = function(self, root, dest, dt, speed, mode)
	local dir = dest - root.Position;
	local dist = dir.Magnitude;
	local np = dest;
	if (dist > 0.05) then
		np = root.Position + (dir.Unit * math.min(speed * dt, dist));
	end
	local cf = CFrame.new(np);
	if (mode == LUAOBFUSACTOR_DECRYPT_STR_0("\62\178\47\117", "\30\122\221\88\27\86\43\68")) then
		cf = cf * CFrame.Angles(-math.pi * 0.5, 0, 0);
		self.AutoFarm.WasDown = true;
	end
	pcall(function()
		root.CFrame = cf;
		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
	end);
end;
