		local decStr = string.format("%.2f", decPart):sub(2);
		decStr = decStr:gsub(LUAOBFUSACTOR_DECRYPT_STR_0("\84\195\118", "\151\100\232\82\20"), "");
		if (decStr ~= ".") then
			return sign .. formatted .. decStr;
		end
	end
	return sign .. formatted;
end;
