Hub.TeleportToLobby = function(self, force)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	if not char then
		return false;
	end
	local root = char:FindFirstChild("HumanoidRootPart");
	local hum = char:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\251\22\123\44\82\206\166\195", "\167\179\99\22\77\60\161\207"));
	if (not root or not hum) then
		return false;
	end
	if (not force and (root.Position.Y > 350)) then
		return false;
	end
	local lobby = self:GetLobby();
	local targetPart = nil;
	if lobby then
		local spawns = lobby:FindFirstChild("Spawns");
		if spawns then
			for _, child in ipairs(spawns:GetChildren()) do
				if child:IsA("BasePart") then
					targetPart = child;
					break;
				end
			end
		end
		if not targetPart then
			for _, desc in ipairs(lobby:GetDescendants()) do
				if (desc:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\50\111\138\79\66\45\112\136\89\88\8\112\133", "\44\97\31\235\56")) or (desc:IsA("BasePart") and string.find(desc.Name:lower(), "spawn"))) then
					targetPart = desc;
					break;
				end
			end
		end
		if not targetPart then
			local pad = self:GetVotePad("VotePad1") or self:GetVotePad(LUAOBFUSACTOR_DECRYPT_STR_0("\199\1\236\161\193\15\252\246", "\196\145\110\152"));
			if pad then
				if pad:IsA("BasePart") then
					targetPart = pad;
				elseif pad:IsA("Model") then
					targetPart = pad.PrimaryPart or pad:FindFirstChildWhichIsA("BasePart", true);
				end
			end
		end
	end
	if not targetPart then
		for _, desc in ipairs(self.Services.Workspace:GetDescendants()) do
			if desc:IsA("SpawnLocation") then
				targetPart = desc;
				break;
			end
		end
	end
	local targetPos = nil;
	if targetPart then
		targetPos = targetPart.Position + Vector3.new(0, 3.5, 0);
	elseif (lobby and lobby:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\117\33\250\247\84", "\146\56\78\158"))) then
		targetPos = lobby:GetPivot().Position + Vector3.new(0, 5, 0);
	end
	if not targetPos then
		return false;
	end
	pcall(function()
		hum.PlatformStand = false;
	end);
	pcall(function()
		hum.Sit = false;
	end);
	pcall(function()
		hum:ChangeState(Enum.HumanoidStateType.Running);
	end);
	pcall(function()
		root.AssemblyLinearVelocity = Vector3.zero;
	end);
	pcall(function()
		root.AssemblyAngularVelocity = Vector3.zero;
	end);
	pcall(function()
		root.Velocity = Vector3.zero;
	end);
	pcall(function()
		root.RotVelocity = Vector3.zero;
	end);
	local _, ry, _ = root.CFrame:ToOrientation();
	root.CFrame = CFrame.new(targetPos) * CFrame.Angles(0, ry, 0);
	self:RestoreCollisions();
	return true;
end;
Hub.GetVotePad = function(self, padName)
	local lobby = self:GetLobby();
	if lobby then
		local votePadsFolder = lobby:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\27\212\91\227\106\44\223\92", "\58\77\187\47\134"));
		if votePadsFolder then
			local p = votePadsFolder:FindFirstChild(padName);
			if p then
				return p;
			end
		end
		local direct = lobby:FindFirstChild(padName);
		if direct then
			return direct;
		end
		local rec = lobby:FindFirstChild(padName, true);
		if rec then
			return rec;
		end
	end
	return self.Services.Workspace:FindFirstChild(padName, true);
