				end
			end
			local voteIcons = (lobby and lobby:FindFirstChild("VoteIcons")) or (lobby and lobby:FindFirstChild("VotePads") and lobby.VotePads:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\123\191\238\195\45\252\170\67\163", "\197\45\208\154\166\100\159")));
			if voteIcons then
				local viPad = voteIcons:FindFirstChild(padName);
